WITH days AS (
 SELECT 'COUPANG' platform,'LEGACY_COUPANG_SINGLE_UPLOAD' scope_key,purchase_date::text business_date,'manual' component,count(*) source_rows FROM meta_ads.coupang_manual_purchases WHERE purchase_date<=DATE '2026-10-29' GROUP BY purchase_date
 UNION ALL SELECT 'NAVER',payload->>'storeId',payload->>'date','fake',count(*) FROM public.daily_fake_purchases WHERE payload->>'storeId' IN('5ba1d3cf-7aee-4cd1-aecd-d44352f665dd','78f8cb08-ffe3-481a-94d7-be87ae93ed79') AND payload->>'date' BETWEEN '2000-01-01' AND '2026-10-29' GROUP BY payload->>'storeId',payload->>'date'
 UNION ALL SELECT 'NAVER',payload->>'storeId',payload->>'date','store_summary',count(*) FROM public.daily_store_summaries WHERE payload->>'storeId' IN('5ba1d3cf-7aee-4cd1-aecd-d44352f665dd','78f8cb08-ffe3-481a-94d7-be87ae93ed79') AND payload->>'date' BETWEEN '2000-01-01' AND '2026-10-29' GROUP BY payload->>'storeId',payload->>'date'
 UNION ALL SELECT 'NAVER',payload->>'storeId',payload->>'date','unit_profit',count(*) FROM public.daily_sales_unit_profits WHERE payload->>'storeId' IN('5ba1d3cf-7aee-4cd1-aecd-d44352f665dd','78f8cb08-ffe3-481a-94d7-be87ae93ed79') AND payload->>'date' BETWEEN '2000-01-01' AND '2026-10-29' GROUP BY payload->>'storeId',payload->>'date'
 UNION ALL SELECT 'NAVER',payload->>'storeId',payload->>'reportDate','ad_receipt',count(*) FROM public.ad_excel_uploads WHERE payload->>'storeId' IN('5ba1d3cf-7aee-4cd1-aecd-d44352f665dd','78f8cb08-ffe3-481a-94d7-be87ae93ed79') AND payload->>'reportDate' BETWEEN '2000-01-01' AND '2026-10-29' GROUP BY payload->>'storeId',payload->>'reportDate'
) SELECT jsonb_build_object('days',(SELECT jsonb_agg(to_jsonb(d) ORDER BY platform,scope_key,business_date,component) FROM days d),'privacy','Scope/day/component counts only, no customer fields') inventory;
